<?php
require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT s.*,u.nombre AS cliente,u.correo,c.id_cotizacion,c.id_administrador,c.diagnostico_preliminar,c.descripcion_trabajo,c.costo_reparacion,c.costo_refacciones,c.costo_total,c.fecha_cotizacion,c.vigencia,c.estado AS estado_cotizacion FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_cliente LEFT JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud WHERE s.id_solicitud=?');$q->execute([$id]);$solicitud=$q->fetch();if(!$solicitud){establecer_mensaje('error','Solicitud no encontrada.');redirigir('solicitudes.php');}$errores=[];if($_SERVER['REQUEST_METHOD']==='POST'){$reparacion=(float)($_POST['costo_reparacion']??-1);$refacciones=(float)($_POST['costo_refacciones']??-1);$descripcion=trim($_POST['descripcion_trabajo']??'');$diagnostico=trim($_POST['diagnostico_preliminar']??'');$vigencia=$_POST['vigencia']??null;if($reparacion<0||$refacciones<0)$errores[]='Los costos no pueden ser negativos.';if($descripcion==='')$errores[]='Describe el trabajo a realizar.';if(!$errores){if($solicitud['id_cotizacion']){$q=$pdo->prepare('UPDATE cotizaciones SET diagnostico_preliminar=?,descripcion_trabajo=?,costo_reparacion=?,costo_refacciones=?,vigencia=?,estado="Pendiente" WHERE id_cotizacion=?');$q->execute([$diagnostico,$descripcion,$reparacion,$refacciones,$vigencia,$solicitud['id_cotizacion']]);}else{$q=$pdo->prepare('INSERT INTO cotizaciones (id_solicitud,id_administrador,diagnostico_preliminar,descripcion_trabajo,costo_reparacion,costo_refacciones,vigencia) VALUES (?,?,?,?,?,?,?)');$q->execute([$id,$_SESSION['usuario']['id_usuario'],$diagnostico,$descripcion,$reparacion,$refacciones,$vigencia]);}$q=$pdo->prepare('UPDATE solicitudes SET estado="Cotizada" WHERE id_solicitud=? AND estado IN ("Pendiente","En revisión","Cotizada")');$q->execute([$id]);establecer_mensaje('exito','Cotización creada correctamente.');redirigir('detalle_solicitud.php?id='.$id);}}$titulo_pagina='Gestionar solicitud';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">SOLICITUD #<?= $id ?></span><h1><?= escapar($solicitud['marca'].' '.$solicitud['modelo']) ?></h1><p>Cliente: <?= escapar($solicitud['cliente']) ?> · <?= escapar($solicitud['correo']) ?></p></div><span class="<?= estado_clase($solicitud['estado']) ?>"><?= escapar($solicitud['estado']) ?></span></div><div class="rejilla-dos"><section class="tarjeta"><h3>Datos reportados</h3><div class="fila-detalle"><span>Problema</span><strong><?= escapar($solicitud['problema_reportado']) ?></strong></div><div class="fila-detalle"><span>Serie</span><strong><?= escapar($solicitud['numero_serie']?:'No indicada') ?></strong></div><div class="fila-detalle"><span>Estado físico</span><strong><?= escapar($solicitud['estado_fisico']?:'No indicado') ?></strong></div><p><?= nl2br(escapar($solicitud['descripcion'])) ?></p></section><section class="formulario-panel"><h2><?= $solicitud['id_cotizacion']?'Editar':'Crear' ?> cotización</h2><?php if($errores): ?><div class="alerta alerta-error"><?= escapar(implode(' ',$errores)) ?></div><?php endif; ?><form method="post" class="formulario" data-costo><label>Diagnóstico preliminar<textarea name="diagnostico_preliminar" required><?= escapar($solicitud['diagnostico_preliminar']??'') ?></textarea></label><label>Trabajo a realizar<textarea name="descripcion_trabajo" required><?= escapar($solicitud['descripcion_trabajo']??'') ?></textarea></label><div class="rejilla-dos"><label>Costo reparación<input type="number" min="0" step="0.01" name="costo_reparacion" required value="<?= escapar($solicitud['costo_reparacion']??0) ?>"></label><label>Costo refacciones<input type="number" min="0" step="0.01" name="costo_refacciones" required value="<?= escapar($solicitud['costo_refacciones']??0) ?>"></label></div><label>Vigencia<input type="date" name="vigencia" required value="<?= escapar($solicitud['vigencia']??date('Y-m-d',strtotime('+15 days'))) ?>"></label><div class="fila-detalle"><span>Total calculado</span><strong class="texto-verde" data-total>$0.00</strong></div><button class="boton" type="submit">Guardar cotización →</button></form></section></div><?php require_once __DIR__.'/../includes/pie.php'; ?>


